<?php
require_once __DIR__.'/includes/layout.php';
$schoolId=tenant_id();$pdo=db();$id=(int)($_GET['id']??0);$qtext=trim((string)($_GET['q']??''));$classId=(int)($_GET['class_id']??0);$status=trim((string)($_GET['status']??''));
$cq=$pdo->prepare('SELECT id,name FROM classes WHERE school_id=:school_id ORDER BY name');$cq->execute(['school_id'=>$schoolId]);$classes=$cq->fetchAll();
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$action=$_POST['_action']??'';$sid=(int)($_POST['id']??0);if($action==='archive'){$s=$pdo->prepare('UPDATE students SET deleted_at=NOW(),status="inactive" WHERE id=:id AND school_id=:school_id');$s->execute(['id'=>$sid,'school_id'=>$schoolId]);audit('archive','students',(string)$sid);flash('success','Student archived.');redirect('students.php');}$data=['admission_no'=>trim((string)($_POST['admission_no']??'')),'first_name'=>trim((string)($_POST['first_name']??'')),'last_name'=>trim((string)($_POST['last_name']??''))?:null,'gender'=>in_array($_POST['gender']??'', ['male','female','other'],true)?$_POST['gender']:null,'date_of_birth'=>($_POST['date_of_birth']??'')?:null,'phone'=>trim((string)($_POST['phone']??''))?:null,'address'=>trim((string)($_POST['address']??''))?:null,'class_id'=>(int)($_POST['class_id']??0)?:null,'status'=>in_array($_POST['status']??'', ['active','inactive','graduated'],true)?$_POST['status']:'active'];if($data['admission_no']===''||$data['first_name']===''){flash('error','Admission number and first name are required.');redirect('students.php');}if($data['class_id']){$c=$pdo->prepare('SELECT id FROM classes WHERE id=:id AND school_id=:school_id');$c->execute(['id'=>$data['class_id'],'school_id'=>$schoolId]);if(!$c->fetchColumn()){flash('error','Selected class is outside the current school.');redirect('students.php');}}try{if($sid){$data+=['id'=>$sid,'school_id'=>$schoolId];$s=$pdo->prepare('UPDATE students SET admission_no=:admission_no,first_name=:first_name,last_name=:last_name,gender=:gender,date_of_birth=:date_of_birth,phone=:phone,address=:address,class_id=:class_id,status=:status WHERE id=:id AND school_id=:school_id');$s->execute($data);audit('update','students',(string)$sid);}else{require_plan_limit('students','students');$data+=['uuid'=>bin2hex(random_bytes(16)),'school_id'=>$schoolId];$s=$pdo->prepare('INSERT INTO students(uuid,school_id,admission_no,first_name,last_name,gender,date_of_birth,phone,address,class_id,status) VALUES(:uuid,:school_id,:admission_no,:first_name,:last_name,:gender,:date_of_birth,:phone,:address,:class_id,:status)');$s->execute($data);audit('create','students',(string)$pdo->lastInsertId());}flash('success','Student saved.');}catch(Throwable){flash('error','Student could not be saved; check duplicate admission number.');}redirect('students.php');}
$edit=null;if($id){$s=$pdo->prepare('SELECT * FROM students WHERE id=:id AND school_id=:school_id');$s->execute(['id'=>$id,'school_id'=>$schoolId]);$edit=$s->fetch();if(!$edit){http_response_code(404);exit('Student not found');}}
$where='s.school_id=:school_id AND s.deleted_at IS NULL';$params=['school_id'=>$schoolId];if($qtext!==''){$where.=' AND (s.admission_no LIKE :q OR s.first_name LIKE :q OR s.last_name LIKE :q OR s.phone LIKE :q)';$params['q']="%$qtext%";}if($classId){$where.=' AND s.class_id=:class_id';$params['class_id']=$classId;}if($status){$where.=' AND s.status=:status';$params['status']=$status;}$s=$pdo->prepare("SELECT s.*,c.name class_name FROM students s LEFT JOIN classes c ON c.id=s.class_id AND c.school_id=s.school_id WHERE $where ORDER BY s.id DESC LIMIT 100");$s->execute($params);$rows=$s->fetchAll();admin_header($edit?'Edit Student':'Students');?><div class="content"><div class="panel"><div class="panel-head"><h2>Student directory</h2><a class="btn" href="#student-form">Add student</a></div><form method="get" class="actions"><input name="q" value="<?=e($qtext)?>" placeholder="Search name, admission number, phone"><select name="class_id"><option value="">All classes</option><?php foreach($classes as $c):?><option value="<?=$c['id']?>" <?=$classId==(int)$c['id']?'selected':''?>><?=e($c['name'])?></option><?php endforeach;?></select><select name="status"><option value="">All statuses</option><?php foreach(['active','inactive','graduated'] as $v):?><option value="<?=$v?>" <?=$status===$v?'selected':''?>><?=$v?></option><?php endforeach;?></select><button class="btn secondary">Filter</button></form><div class="table-wrap"><table><thead><tr><th>Admission</th><th>Name</th><th>Class</th><th>Phone</th><th>Status</th><th>Actions</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['admission_no'])?></td><td><?=e(trim($r['first_name'].' '.$r['last_name']))?></td><td><?=e($r['class_name']??'Unassigned')?></td><td><?=e($r['phone'])?></td><td><?=e($r['status'])?></td><td><a class="btn secondary" href="students.php?id=<?=$r['id']?>">Edit</a><form method="post" style="display:inline"><input type="hidden" name="_csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="_action" value="archive"><input type="hidden" name="id" value="<?=$r['id']?>"><button class="btn secondary">Archive</button></form></td></tr><?php endforeach;if(!$rows):?><tr><td class="empty" colspan="6">No students found.</td></tr><?php endif;?></tbody></table></div></div><div class="panel" id="student-form"><h2><?=$edit?'Edit student':'Add student'?></h2><form class="grid" method="post"><input type="hidden" name="_csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=e($edit['id']??0)?>"><div class="field"><label>Admission number</label><input name="admission_no" required value="<?=e($edit['admission_no']??'')?>"></div><div class="field"><label>First name</label><input name="first_name" required value="<?=e($edit['first_name']??'')?>"></div><div class="field"><label>Last name</label><input name="last_name" value="<?=e($edit['last_name']??'')?>"></div><div class="field"><label>Class</label><select name="class_id"><option value="">Unassigned</option><?php foreach($classes as $c):?><option value="<?=$c['id']?>" <?=((int)($edit['class_id']??0)===(int)$c['id'])?'selected':''?>><?=e($c['name'])?></option><?php endforeach;?></select></div><div class="field"><label>Gender</label><select name="gender"><option value="">Select</option><?php foreach(['male','female','other'] as $v):?><option value="<?=$v?>" <?=($edit['gender']??'')===$v?'selected':''?>><?=$v?></option><?php endforeach;?></select></div><div class="field"><label>Date of birth</label><input type="date" name="date_of_birth" value="<?=e($edit['date_of_birth']??'')?>"></div><div class="field"><label>Phone</label><input name="phone" value="<?=e($edit['phone']??'')?>"></div><div class="field"><label>Status</label><select name="status"><?php foreach(['active','inactive','graduated'] as $v):?><option value="<?=$v?>" <?=($edit['status']??'active')===$v?'selected':''?>><?=$v?></option><?php endforeach;?></select></div><div class="field full"><label>Address</label><textarea name="address"><?=e($edit['address']??'')?></textarea></div><div class="actions"><button class="btn">Save student</button></div></form></div></div><?php admin_footer();
